import {domainFor} from './core.js?v=20261015-template';
export const PHASE_COLOURS={single:'#00a6ff',three:'#ff9d00',unknown:'#a5abb4'};
const key=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]/g,'');
export function countField(field){return ['numberofphases','numberphases','phasecount','noofphases','numphases'].includes(key(field?.name))||['numberofphases','numberphases','phasecount'].includes(key(field?.alias));}
export function phaseField(meta){const fields=meta.fields.filter(f=>['esriFieldTypeString','esriFieldTypeInteger','esriFieldTypeSmallInteger','esriFieldTypeDouble'].includes(f.type));return fields.find(countField)?.name||fields.find(f=>['phases','phase','phasedesignation','phasesnormal'].includes(key(f.name)))?.name||'';}
export function phaseClass(meta,attrs,name){const field=meta.fields.find(f=>f.name===name);if(!field)return 'unknown';const raw=attrs[name];if(raw==null||String(raw).trim()==='')return 'unknown';const domain=domainFor(meta,field,attrs);let value=raw;if(domain?.type==='codedValue'){const item=domain.codedValues.find(c=>c.code===raw);if(!item)return 'unknown';value=item.name;}const text=key(value);if(['singlephase','1phase','phase1','single','a','b','c','an','bn','cn','phasea','phaseb','phasec','phasean','phasebn','phasecn'].includes(text))return 'single';if(['threephase','3phase','phase3','three','abc','abcn','phaseabc','phaseabcn','phasesabc','phasesabcn'].includes(text))return 'three';if(countField(field)){if(text==='1')return 'single';if(text==='3')return 'three';}return 'unknown';}
export function phaseStyle(kind,phase,missing){const color=PHASE_COLOURS[phase]||PHASE_COLOURS.unknown;return {color:kind==='point'?(missing?'#ff3030':'#172d30'):color,fillColor:color,fillOpacity:.95,weight:kind==='point'?(missing?3:1.5):3,dashArray:kind!=='point'&&missing?'7 4':null};}
